    R0 = flags;
    R1 = mask;
    GUEST_CALL(sprite_removeShadow);
    return R0;
}

/* NPC script command "remove shadow": mark the NPC's shadow as removed
 * (set 0x80), cancel any pending shadow request (clear 0x100) in
 * UnkFlags_60, tell the sprite system to drop the shadow, and advance
 * the script program counter. Returns the advanced counter. */
static u32 npc_command_remove_shadow(u32 npc, u32 script_pc) {
    u32 flags = LD32(npc + oOverworldNPCObject_UnkFlags_60);

    flags |= OW_NPC_UNK_FLAGS_60_SHADOW_FLAG_0x80;
    ST32(npc + oOverworldNPCObject_UnkFlags_60, flags);

    flags &= ~0x100u; /* OW_NPC_UNK_FLAGS_60_SHADOW_FLAG_0x100 */
    ST32(npc + oOverworldNPCObject_UnkFlags_60, flags);

    call_sprite_removeShadow(flags, 0x100u);

    return script_pc + 1;
}

/* NPCCommand_remove_shadow(r5 = NPC object, r6 = script program counter)
 * -> r6 advanced by one; nz/c/v from the increment. r0/r1/r3 are left as
 * sprite_removeShadow left them. */
Next NPCCommand_remove_shadow(void) {
    R6 = npc_command_remove_shadow(R5, R6);
    SET_FLAGS_ADD(R6, 1);
    RETURN_TO_CALLER();
}

