 * 0x100 flag, hand the resulting flags to the sprite layer, and bump the
 * NPC command counter. r5 = NPC object, r6 = command counter.
 * Returns the incremented counter (the original's ADDS r6, #1). */
static u32 npc_command_remove_shadow(u32 npc, u32 r6)
{
