/* sub_81280DC — rebuilds the NPC entry tile buffer at unk_2026700.
 *
 * The buffer is zeroed, then for every NPC (up to four 0x5C-byte blocks) a call to
 * npc_checkEntryEventFlagOrHidden_812818C decides the starting tile index (and the
 * attribute bits used for the first section). Each block holds two mirrored halves
 * 0x2E bytes apart: every stored halfword pair gets the tile index and tile index+1,
 * OR'd with attribute bits. Three sections are written per half; the halfword slot
 * between sections (offsets 0x16 and 0x28) and its tile index stay unused.
 */
#define NPC_ENTRY_BUFFER   A_unk_2026700
#define NPC_BUFFER_BYTES   0x170u    /* 4 blocks * 0x5C bytes */
#define NPC_BLOCK_BYTES    0x5Cu
#define NPC_MIRROR_OFFSET  0x2Eu     /* 0x17 << 1: second half of the block */

#define NPC_ENTRY_ATTR     (7u << 12)
#define NPC_HIDDEN_ATTR    0x9000u

/* register form: calls ZeroFillByByte outside this file, which has no typed C interface yet */
static void zero_fill(u32 addr, u32 num_bytes) {
    R0 = addr;
    R1 = num_bytes;
    GUEST_CALL(ZeroFillByByte);
}

/* register form: calls npc_checkEntryEventFlagOrHidden_812818C outside this file, which has no typed C interface yet */
static u32 query_npc_entry(u32 base_tile, u32 block_offset, u32 attr, u32 *attr_out) {
    R0 = base_tile;
    R1 = block_offset;
    R2 = attr;
    GUEST_CALL(npc_checkEntryEventFlagOrHidden_812818C);
    *attr_out = R2;   /* the callee's r2 is the attribute used for the first section */
    return R0;        /* the callee's r0 is the starting tile index for this block */
}

/* Store halfword pairs for one section: block[off] = tile|attr and the mirrored half
 * at +0x2E gets (tile|attr)+1, consuming two tile indices per pair. Returns the tile
 * index after the section. */
static u32 write_section(u32 block, u32 mirror, u32 off, u32 end, u32 attr, u32 tile) {
    while (off < end) {
        u32 value = tile | attr;
        ST16(block + off, value);
        ST16(mirror + off, value + 1);
        tile += 2;
        off += 2;
    }
    return tile;
}

static void fill_npc_map_data(u32 base_tile, u32 npc_count) {
    zero_fill(NPC_ENTRY_BUFFER, NPC_BUFFER_BYTES);

    u32 tile = base_tile;
    for (s32 npc = 0; npc < (s32)npc_count; npc++) {
        u32 block = NPC_ENTRY_BUFFER + (u32)npc * NPC_BLOCK_BYTES;
        u32 mirror = block + NPC_MIRROR_OFFSET;
        u32 attr = NPC_ENTRY_ATTR;

        tile = query_npc_entry(tile, (u32)npc * NPC_BLOCK_BYTES, NPC_ENTRY_ATTR, &attr);
        tile = write_section(block, mirror, 0x00, 0x16, attr, tile);
        tile += 2;  /* the slot between sections and its tile index stay unused */
        tile = write_section(block, mirror, 0x18, 0x28, NPC_HIDDEN_ATTR, tile);
        tile += 2;
        write_section(block, mirror, 0x2A, 0x2E, NPC_ENTRY_ATTR, tile);
        /* tile carries into the next NPC's query */
    }
}

/* sub_81280DC(r0 = base tile index, r1 = NPC count) -> r1 r2 r3, c v
 * On exit the original leaves r1 = r3 = the NPC count, r2 = NPC_ENTRY_ATTR, and the
 * flags from the final count comparison (equal counts: C set, V clear). r1 and
 * r4-r7 are preserved. */
Next sub_81280DC(void) {
    u32 count = R1;
    fill_npc_map_data(R0, count);
    R2 = NPC_ENTRY_ATTR;
    R3 = count;
    SET_FLAGS_CMP(count, count);
    RETURN_TO_CALLER();
}

