/* Switch to the jack-in cut-in sequence (START/B, or A on the jack-in spot). */
static void begin_jack_in_sequence(u32 work) {
    ST8(work + PET_STATE, 8);
    ST8(work + PET_JACKIN_FLAG, 1);
    load_gfx_anim(A_byte_811EB04);
    load_gfx_anim(A_byte_811EB5C);
