/* Handle one frame of menu input once the cooldown has run out. */
static void handle_pet_menu_input(u32 work, u32 toolkit) {
    if (button_pressed(JOYPAD_START | JOYPAD_B)) {
        begin_jack_in_sequence(work);
        return;
    }

    u32 cursor = LD8(work + PET_CURSOR);

    if (button_pressed(JOYPAD_A)) {
        if (cursor >= 8) {
            /* A on the jack-in spot starts the jack-in. */
            begin_jack_in_sequence(work);
            return;
        }
        if (pet_comm_save_disabled() && (cursor == 6 || cursor == 7)) {
            /* These two slots are locked out while comm/save is disabled. */
            play_sound_effect(SOUND_CANT_JACK_IN);
            /* still allow cursor movement this frame, as in the original */
        } else {
            play_sound_effect(SOUND_MENU_SELECT);
            ST8(work + PET_STATE, 0x10);
            ST8(work + PET_STATE_PARAM, 4);
            return;
        }
    }

    if (cursor >= 8) {
        /* On the jack-in spot: any direction key steps back to the icon row. */
        if (button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT)) {
            play_sound_effect(SOUND_MENU_CUR_MOVE);
            ST8(work + PET_CURSOR, LD8(work + PET_PREV_CURSOR));
            ST8(work + PET_INPUT_COOLDOWN, 3);
        }
        return;
    }

    if (button_pressed(JOYPAD_RIGHT)) {
        /* Move onto the jack-in spot. */
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(work + PET_PREV_CURSOR, cursor);
        ST8(work + PET_CURSOR, 8);
        ST8(work + PET_FIELD_06, 0);
        ST8(work + PET_FIELD_07, 0);
        return;
    }

    /* Up/down over the icon row, using the low-sensitivity held mask. */
    u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
    u32 held = LD16(joypad + oJoypad_LowSensitivityHeld);
    ST8(work + PET_CURSOR, move_cursor_up_down(held, 8, 1, cursor));
}

/* One tick of the PET jack-in menu screen. */
static void pet_screen_update(u32 work, u32 toolkit) {
    copy_background_tiles_pet();
    copy_background_tiles_on_navi_select();
    call_sub_811F24C();

    if (!gfx_anim_active(0x10)) {
        u32 cooldown = LD8(work + PET_INPUT_COOLDOWN);
        if (cooldown != 0) {
            /* wait a few frames after a cursor move before accepting input */
            ST8(work + PET_INPUT_COOLDOWN, cooldown - 1);
        } else if (screen_fade_active()) {
            handle_pet_menu_input(work, toolkit);
        }
    }

    call_sub_811F1B8();
    call_sub_811F0C8();
    call_sub_811F11C();
}

