/* If the tutorial step asks for a chat, pick its next script and hand it to
 * the chatbox, then put the chatbox into its 0x34 "script running" wait. */
static void start_tutorial_chat(u32 work) {
    u32 step = LD8(work + 0xC);

    if (step == 0xFF)
        return;

    u32 script_idx;
    switch (step) {
    case 0:
        script_idx = pick_tutorial_script_step0(step);
        break;
    case 1:
        script_idx = pick_tutorial_script_step1(step);
        break;
    case 3:
        script_idx = pick_tutorial_script_step3(step);
        break;
    default:
        return;
    }

    if (script_idx == 0) /* picker says nothing more to say for now */
        return;

    /* Re-read the step: the picker may have advanced it. */
    u32 step_now = LD8(work + 0xC);
    u32 archive = LD32(A_TextScriptFirstBattleTutorials + step_now * 4);
    run_chatbox_script(archive, script_idx, step_now * 4);

    /* Chatbox takes over: remember the old state byte and start the wait. */
    ST8(work + 0xD, LD8(work + 1));
    ST8(work + 1, 0x34);
    ST16(work + 2, 0);
}

