 * r5/r6/r7 pass through untouched; r2/r3 are left behind by the guest calls,
 * exactly as the original leaves them. */
static void run_battle_tutorial_text(u32 obj) {
    u32 step = LD8(obj + TUTOBJ_step);
    u32 script_idx;

    if (step == 0xFF)
        return;

    if (step == 0)
        script_idx = tutorial_script_step0(step);
    else if (step == 1)
        script_idx = tutorial_script_step1(step);
    else if (step == 3)
        script_idx = tutorial_script_step3(step);
    else
        return;

    if (script_idx == 0)
        return;

    /* The original re-reads the step byte here, so a helper that changed it
     * would select a different table entry. */
    u32 step_now = LD8(obj + TUTOBJ_step);
    u32 archive = LD32(A_TextScriptFirstBattleTutorials + (step_now << 2));
    run_tutorial_chatbox_script(archive, script_idx, step_now << 2);

    /* Text box is now open: park the old action and reset the timer. */
    ST8(obj + TUTOBJ_prev_action, LD8(obj + TUTOBJ_action));
    ST8(obj + TUTOBJ_action, 0x34);
    ST16(obj + TUTOBJ_timer, 0);
}

