/* First word of each GFX animation stream entry acts as an opcode: */
#define GFX_ANIM_ENTRY_END       0   /* no more entries: the animation deactivates */
#define GFX_ANIM_ENTRY_LOOP      1   /* restart from the remembered loop point */
#define GFX_ANIM_ENTRY_SET_LOOP  2   /* remember the given address as the loop point */

/* Animation types, as set up by LoadGFXAnim. The values are byte offsets into
 * the per-type tables (stream offsets in byte_8001C08, handlers in off_8001C24). */
enum {
    GFX_ANIM_CMD_COPY_PALETTE      = 0x00, /* upload the next palette */
    GFX_ANIM_CMD_COPY_TILES_0X20   = 0x04, /* copy 0x20-sized tiles */
    GFX_ANIM_CMD_08                = 0x08, /* ??? */
    GFX_ANIM_CMD_PALETTE_TRANSFORM = 0x0c, /* manual palette transform */
    GFX_ANIM_CMD_PLAY_SFX          = 0x10, /* play a sound effect */
    GFX_ANIM_CMD_EVENT_FLAG        = 0x14, /* set or clear an event flag */
    GFX_ANIM_CMD_COPY_TILES_0X40   = 0x18, /* copy 0x40-sized tiles */
};

