    R0 = params;    /* pointer to the current stream entry */
    R1 = command;   /* register contents the original call site leaves behind */
    R2 = command;
    R3 = caller_r12;
    R7 = self;
    switch (command) {
    case GFX_ANIM_CMD_COPY_PALETTE:      GUEST_CALL(sprite_QueueAnimFrameGfxUpload_8001C44); break;
    case GFX_ANIM_CMD_COPY_TILES_0X20:   GUEST_CALL(sub_8001C94);                            break;
    case GFX_ANIM_CMD_08:                GUEST_CALL(sub_8001C52);                            break;
    case GFX_ANIM_CMD_PALETTE_TRANSFORM: GUEST_CALL(sprite_gfxAnimState_GotoNext_8002310);   break;
    case GFX_ANIM_CMD_PLAY_SFX:          GUEST_CALL(sub_800232A);                            break;
    case GFX_ANIM_CMD_EVENT_FLAG:        GUEST_CALL(sub_8002338);                            break;
    case GFX_ANIM_CMD_COPY_TILES_0X40:   GUEST_CALL(sub_8001CFC);                            break;
