/* Advance every active GFX animation by one step: tick its frame timer and, once
 * it expires, move to the next entry of its command stream and run that entry
 * through the handler for the animation's type. */
static void process_gfx_anim_states(u32 caller_r12) {
    u32 state = A_eGFXAnimState0;

    for (u32 i = 0; i < NUM_GFX_ANIMS; i++, state += oGFXAnimState_Size) {
        if (LD8(state + oGFXAnimState_IsActive) == 0)
            continue;

        /* tick the frame delay; the entry is only processed once it drops to 0 */
        u32 timer = LD16(state + oGFXAnimState_Timer) - 1;
        ST16(state + oGFXAnimState_Timer, timer);
        if ((s32)timer > 0)
            continue;

        /* the next entry sits at a per-type offset from the stream position */
        u32 command = LD8(state + oGFXAnimState_Command);
        u32 entry = LD32(state + oGFXAnimState_CommandPos)
                  + LD32(A_byte_8001C08 + command);

        u32 opcode = LD32(entry);
        u32 next;
        if (opcode == GFX_ANIM_ENTRY_END) {
            /* end of the stream: stop the animation (stream position untouched) */
            ST8(state + oGFXAnimState_IsActive, 0);
            continue;
        } else if (opcode == GFX_ANIM_ENTRY_SET_LOOP) {
            /* "set loop point" marker: jump to and remember the given address */
            next = LD32(entry + 4);
