            ST8(state + oGFXAnimState_IsActive, 0);
            continue;
        } else if (op == 1) {
            /* Loop: resume from the recorded loop point. */
            next = LD32(state + oGFXAnimState_LoopAddress);
        } else if (op == 2) {
            /* New loop point: record it and continue from there. */
            next = LD32(entry + 4);
            ST32(state + oGFXAnimState_LoopAddress, next);
        } else {
