        case 0: gfx_anim_cmd_upload_palette(next, state);    break;
        case 1: gfx_anim_cmd_copy_tiles_20(next, state);     break;
        case 2: gfx_anim_cmd_unknown_2(next, state);         break;
        case 3: gfx_anim_cmd_palette_transform(next, state); break;
        case 4: gfx_anim_cmd_play_sfx(next, state);          break;
        case 5: gfx_anim_cmd_event_flag(next, state);        break;
        case 6: gfx_anim_cmd_copy_tiles_40(next, state);     break;
