    /* START or B leaves the screen from anywhere. */
    if (button_pressed(0xA /* JOYPAD_START | JOYPAD_B */)) {
        begin_screen_transition(work);
        return;
    }

    if (!button_pressed(1 /* JOYPAD_A */)) {
        handle_cursor_movement(work, toolkit);
        return;
    }

    u32 cursor = LD8(work + PET_CURSOR);

    /* A in the lower area behaves like START/B. */
    if (cursor >= 8) {
        begin_screen_transition(work);
        return;
    }

    /* A on one of the eight menu slots. */
    if (pet_comm_save_disabled() && (cursor == 6 || cursor == 7)) {
        /* These two slots are unusable while pet comm saving is disabled;
         * the original then still runs the cursor handling below. */
        play_sound_effect(SOUND_CANT_JACK_IN);
        handle_cursor_movement(work, toolkit);
        return;
    }

    play_sound_effect(SOUND_MENU_SELECT);
    ST8(work + PET_STATE, 0x10);
    ST8(work + PET_NEXT_STATE, 4);
}

