/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet.
 * Clears the tally table. Returns r1 as that callee leaves it, because the original's final
 * r1 derives from this value whenever no later loop iteration overwrites r1. */
static u32 clear_tally_table(void) {
    R0 = TALLY_TABLE;
    R1 = TALLY_TABLE_BYTES;
    GUEST_CALL(ZeroFillByEightWords);
    return R1;
