/* First tally slot whose id is free (0) or already equals id. */
static u32 find_tally_slot(u32 table, u32 id) {
    for (u32 slot = 0; ; slot += TALLY_SLOT) {
        u32 entry = LD16(table + slot);
        if (entry == 0 || entry == id)
            return slot;
    }
}

static TallyResult tally_record_ids(u32 recordCount, u32 r2In) {
    TallyResult out;
    u32 records = RECORD_LIST;
    u32 recordsEnd = records + recordCount * RECORD_STRIDE;
    u32 table = TALLY_TABLE;

    /* The original keeps the running count on the stack and leaves scraps in r1/r2;
     * both are part of the register contract, so track them explicitly. */
    u32 r1 = clear_tally_table();
    u32 r2 = r2In;
    u32 nonzeroIds = 0;

    /* Pass 1: build the id -> occurrence-count table. */
    u32 rec = records;
    do {
        u32 id = LD16(rec);
        if (id != 0) {
            nonzeroIds++;
            r2 = nonzeroIds;
            u32 slot = find_tally_slot(table, id);
            if (LD16(table + slot) == 0) {
                ST16(table + slot, id);        /* claim free slot... */
                ST8(table + slot + 2, 1);      /* ...with an initial count of 1 */
                r1 = 0;
            } else {
                u32 hits = LD16(table + slot + 2) + 1;
                ST16(table + slot + 2, hits);
                r1 = hits;
            }
        }
        rec += RECORD_STRIDE;
    } while ((s32)rec < (s32)recordsEnd);

    /* Pass 2: stamp each record's reference id with its tally count. */
    rec = records;
    do {
        u32 id = LD16(rec + RECORD_REF_ID);
        if (id != 0) {
            u32 slot = find_tally_slot(table, id);
            r1 = id;   /* the original ends this step with the record's id in r1 */
            ST32(rec + RECORD_REF_ID, (LD16(table + slot + 2) << 16) | id);
        }
        rec += RECORD_STRIDE;
    } while ((s32)rec < (s32)recordsEnd);

    out.count = nonzeroIds;
    out.r1 = r1;
    out.r2 = r2;
    return out;
}

