static struct MsgboxCommandResult chatbox_msgbox_command(u32 script, u32 chatbox) {
    struct MsgboxCommandResult out;
    u32 opcode = LD8(script + 1);
    u32 fieldOff = oChatbox_Unk_1D2; /* the original also passes 0x1D2 to the worker in r2 */
    u32 tableBase = A_chatbox_EB_msgboxJumpTable;
    u32 styleArg;
    struct ChatboxWorkerRegs worker;

    /* Store the frame type this command selects into the chatbox properties. */
    if (opcode >= 0x10) {
        ST8(chatbox + fieldOff, 6);
        styleArg = 6;
    } else if (opcode >= 0xC) {
        ST8(chatbox + fieldOff, 5);
        styleArg = 5;
    } else if (opcode >= 8) {
        ST8(chatbox + fieldOff, 4);
        styleArg = 4;
    } else if (opcode < 4) {
        ST8(chatbox + fieldOff, 0);
        styleArg = 0;
    } else {
        /* Opcodes 4..7 take the frame type from the script stream itself and
         * optionally reposition the text cursor from byte_8045DCC. */
