            ST8(chatbox + oChatbox_CursorIdx, LD16(cursorPos));      /* ChatBoxProperties.csrCoord */
            ST8(chatbox + oChatbox_Unk_1B, LD16(cursorPos + 2));     /* ChatBoxProperties.unk_1B   */
            styleArg *= 4; /* r3 holds the cursor-table offset when the worker runs */
        }
