     * 16 and 17 select the last two entries. Script data never goes beyond
     * 17, so larger opcodes (which would read past the table in the
     * original) are dispatched like 17 here. */
    if (opcode < 0x10) {
        switch (opcode & 3) {
        case 0:  worker = call_chatbox_804103E(tableBase, opcode, fieldOff, styleArg); break;
        case 1:  worker = call_chatbox_8041090(tableBase, opcode, fieldOff, styleArg); break;
        case 2:  worker = call_chatbox_closeAndReset_80410F8(tableBase, opcode, fieldOff, styleArg); break;
        default: worker = call_chatbox_804110C(tableBase, opcode, fieldOff, styleArg); break;
        }
    } else if (opcode == 0x10) {
        worker = call_chatbox_closeAndReset_80410F8(tableBase, opcode, fieldOff, styleArg);
    } else {
        worker = call_chatbox_804110C(tableBase, opcode, fieldOff, styleArg);
    }

    if (worker.r0 != 0) {
        /* Worker finished the command: skip it using the per-opcode step.
         * The original leaves r0 = &byte_804102C and r1 = step here, and
         * `adds r4, r4, r1` as the last flag-setting instruction (the sum
         * never carries or overflows for these values). */
        u32 step = LD8(A_byte_804102C + opcode);
        out.nextScript = script + step;
        out.outR0 = A_byte_804102C;
        out.outR1 = step;
        SET_FLAGS_ADD(out.nextScript, 0);
    } else {
        /* Worker needs more frames: keep the script pointer and the worker's
         * r0/r1; `tst r0,r0` only refreshes N/Z, leaving the worker's C/V. */
        out.nextScript = script;
        out.outR0 = worker.r0;
        out.outR1 = worker.r1;
        SET_FLAGS_NZ(worker.r0);
    }
    return out;
}

