    u32 regularArea = get_work_area_2006CF8();
    for (slot = 6; slot >= 0; slot--) {
        u32 id = LD8(regularArea + slot);
        if (id == 0)
            continue;
        u32 entryValue = LD16(get_ncp_entry_ptr(id - 1));
        lastEntryValue = entryValue;
        if (entryValue == 0)
            continue;
        u32 letter = LD8(get_ncp_letter_ptr(entryValue));
        if (letter != 0) {
            ST8(A_byte_2006DD8 + slot, letter);
            if (ncp_letter_appears_later(A_byte_2006DD8, slot, letter))
