        }
        run_ncp_handler(entryValue, slot, regularArea);
    }

    /* Pass 2: first 49-slot list, handlers run unconditionally. */
    u32 listArea = get_work_area_813BD10();
    for (slot = 0; slot < 0x31; slot++) {
        u32 id = LD8(listArea + slot);
        if (id == 0)
            continue;
        u32 entryValue = LD16(get_ncp_entry_ptr(id - 1));
        lastEntryValue = entryValue;
        if (entryValue == 0)
