    u32 extraArea = get_work_area_2006CC0();
    for (slot = 0; slot < 0x31; slot++) {
        u32 id = LD8(extraArea + slot);
        if (id == 0)
            continue;
        u32 entryValue = LD16(get_ncp_entry_ptr(id - 1));
        lastEntryValue = entryValue;
        if (entryValue == 0)
            continue;
        run_ncp_handler(entryValue, slot, extraArea);
    }

    petnavi_set_stat42_to_stat3e(lastEntryValue, 0x31, extraArea);
